import{checkEncCryptoKey}from"./crypto_key.js";import{checkKeyLength}from"./signing.js";import{JOSENotSupported}from"../util/errors.js";const subtleAlgorithm=t=>{switch(t){case"RSA-OAEP":case"RSA-OAEP-256":case"RSA-OAEP-384":case"RSA-OAEP-512":return"RSA-OAEP";default:throw new JOSENotSupported(`alg ${t} is not supported either by JOSE or your javascript runtime`)}};export async function encrypt(t,e,r){return checkEncCryptoKey(e,t,"encrypt"),checkKeyLength(t,e),new Uint8Array(await crypto.subtle.encrypt(subtleAlgorithm(t),e,r))}export async function decrypt(t,e,r){return checkEncCryptoKey(e,t,"decrypt"),checkKeyLength(t,e),new Uint8Array(await crypto.subtle.decrypt(subtleAlgorithm(t),e,r))}